servers.onUp:
function onUp() {
  // Coordinator
  const fsm = new Automat({
    initial: 'idle',
    states: {
      idle:       { on: { START: 'prepare' },    color: '#8bc34a' },
      prepare:    { on: { ALL_SENT: 'collecting' }, color: '#ffc107' },
      collecting: { on: { ALL_VOTED: 'committing', TIMEOUT: 'aborting' }, color: '#ff9800' },
      committing: { on: { DONE: 'idle' },         color: '#2196f3' },
      aborting:   { on: { DONE: 'idle' },         color: '#f44336' },
    }
  });
  dumpState({ fsm: fsm.serialize(), txId: 0, outbox: [], votes: {} });
}

servers.onTimer:
function onTimer(tick) {
  let s = loadState();
  const fsm = Automat.deserialize(s.fsm);
  s.tick = tick;

  // 1. idle -> prepare (every 30 ticks)
  if (fsm.state === 'idle' && tick > 0 && tick % 30 === 0) {
    s.txId++;
    fsm.transition('START');
    const targets = allServerIds.filter(id => id !== serverId);
    s.outbox = targets.map(id => ({ to: id, msg: { type: 'PREPARE', txId: s.txId, data: 'X=' + s.txId } }));
    s.votes = {};
    s.phaseStart = tick;
  }

  // 2. prepare -> collecting
  if (fsm.state === 'prepare') {
    if (s.outbox.length > 0) {
      const t = s.outbox.pop();
      sendMessage(t.to, t.msg);
    }
    if (s.outbox.length === 0) {
      fsm.transition('ALL_SENT');
    }
  }

  // 3. collecting timeouts
  if (fsm.state === 'collecting' && tick - s.phaseStart > 15) {
    fsm.transition('TIMEOUT');
    const targets = allServerIds.filter(id => id !== serverId);
    s.outbox = targets.map(id => ({ to: id, msg: { type: 'ABORT', txId: s.txId } }));
  }

  // 4. committing / aborting -> idle
  if ((fsm.state === 'committing' || fsm.state === 'aborting') && s.outbox.length > 0) {
    const t = s.outbox.pop();
    sendMessage(t.to, t.msg);
  }
  if ((fsm.state === 'committing' || fsm.state === 'aborting') && s.outbox.length === 0) {
    fsm.transition('DONE');
  }

  s.fsm = fsm.serialize();
  dumpState(s);
}

servers.onMessage:
function onMessage(message) {
  let s = loadState();
  const fsm = Automat.deserialize(s.fsm);
  const m = message.payload;

  if (fsm.state === 'collecting' && m.txId === s.txId) {
    if (m.type === 'VOTE_COMMIT') s.votes[message.from] = 'yes';
    if (m.type === 'VOTE_ABORT') s.votes[message.from] = 'no';

    const expected = allServerIds.filter(id => id !== serverId);
    const allVoted = expected.every(id => s.votes[id] !== undefined);

    if (allVoted) {
      const allYes = expected.every(id => s.votes[id] === 'yes');
      if (allYes) {
        fsm.transition('ALL_VOTED');
        s.outbox = expected.map(id => ({ to: id, msg: { type: 'COMMIT', txId: s.txId } }));
      } else {
        fsm.transition('TIMEOUT'); // transition to aborting
        s.outbox = expected.map(id => ({ to: id, msg: { type: 'ABORT', txId: s.txId } }));
      }
    }
  }

  s.fsm = fsm.serialize();
  dumpState(s);
}

servers.onUp:
function onUp() {
  // Cohort
  const fsm = new Automat({
    initial: 'ready',
    states: {
      ready:     { on: { PREPARE: 'voted_yes' }, color: '#b2dfdb' },
      voted_yes: { on: { COMMIT: 'ready', ABORT: 'ready' }, color: '#4db6ac' },
    }
  });
  dumpState({ fsm: fsm.serialize(), data: null, pendingTx: null, history: [] });
}

servers.onTimer:
function onTimer(tick) {
  let s = loadState();
  s.tick = tick;
  dumpState(s);
}

servers.onMessage:
function onMessage(message) {
  let s = loadState();
  const fsm = Automat.deserialize(s.fsm);
  const m = message.payload;

  if (m.type === 'PREPARE' && fsm.can('PREPARE')) {
    fsm.transition('PREPARE');
    s.pendingTx = m.txId;
    s.pendingData = m.data;
    sendMessage(message.from, { type: 'VOTE_COMMIT', txId: m.txId });
  }

  if (m.type === 'COMMIT' && s.pendingTx === m.txId && fsm.can('COMMIT')) {
    fsm.transition('COMMIT');
    s.data = s.pendingData;
    s.history.push('TX' + m.txId + ':commit');
    s.pendingTx = null;
    s.pendingData = null;
    sendMessage(message.from, { type: 'ACK', txId: m.txId });
  }

  if (m.type === 'ABORT' && s.pendingTx === m.txId && fsm.can('ABORT')) {
    fsm.transition('ABORT');
    s.history.push('TX' + m.txId + ':abort');
    s.pendingTx = null;
    s.pendingData = null;
    sendMessage(message.from, { type: 'ACK', txId: m.txId });
  }

  s.fsm = fsm.serialize();
  dumpState(s);
}
